import { describe, expect, it, vi, beforeEach, afterEach } from "vitest";
import { credentialFingerprint, getBotData, getConversationHistory } from "./api";

const PROJECT_URL = "http://localhost:5005";
const BOT_DATA_ENDPOINT = "/data";
const TRACKER_ENDPOINT = "/conversations/test-session/tracker";

const BOT_DATA_RESPONSE = {
  flows: {},
  assistant_id: "test-assistant",
};

const TRACKER_RESPONSE = {
  sender_id: "test-session",
  events: [],
  latest_message: null,
  slots: {},
  stack: [],
};

describe("api", () => {
  const originalFetch = global.fetch;

  const mockFetchOnce = (payload: unknown) => {
    vi.mocked(global.fetch).mockResolvedValueOnce({
      ok: true,
      json: () => Promise.resolve(payload),
    } as Response);
  };

  const lastRequest = () => {
    const fetchMock = vi.mocked(global.fetch);
    expect(fetchMock).toHaveBeenCalledTimes(1);
    const [requestedUrl, requestInit] = fetchMock.mock.calls[0];
    return { requestedUrl, requestInit };
  };

  const fetchBotData = async (httpAuth?: Parameters<typeof getBotData>[0]["httpAuth"]) => {
    mockFetchOnce(BOT_DATA_RESPONSE);
    await getBotData({ projectUrl: PROJECT_URL, botDataEndpoint: BOT_DATA_ENDPOINT, httpAuth });
    return lastRequest();
  };

  const fetchConversationHistory = async (
    httpAuth?: Parameters<typeof getConversationHistory>[0]["httpAuth"],
  ) => {
    mockFetchOnce(TRACKER_RESPONSE);
    await getConversationHistory({
      projectUrl: PROJECT_URL,
      trackerEndpoint: TRACKER_ENDPOINT,
      httpAuth,
    });
    return lastRequest();
  };

  beforeEach(() => {
    global.fetch = vi.fn();
  });

  afterEach(() => {
    global.fetch = originalFetch;
    vi.clearAllMocks();
  });

  describe("getBotData", () => {
    it("requests the plain URL when no credential is provided", async () => {
      const { requestedUrl } = await fetchBotData();
      expect(requestedUrl).toBe(`${PROJECT_URL}${BOT_DATA_ENDPOINT}`);
    });

    it("appends the token query parameter for query transport, and no header", async () => {
      const { requestedUrl, requestInit } = await fetchBotData({
        token: "test-token-123",
        via: "query",
      });
      expect(requestedUrl).toBe(`${PROJECT_URL}${BOT_DATA_ENDPOINT}?token=test-token-123`);
      expect(requestInit?.headers).not.toHaveProperty("Authorization");
    });

    it("sends a Bearer Authorization header for header transport, and no query token", async () => {
      const { requestedUrl, requestInit } = await fetchBotData({
        token: "session-token-123",
        via: "header",
      });
      expect(requestInit?.headers).toMatchObject({
        Authorization: "Bearer session-token-123",
      });
      expect(requestedUrl).not.toContain("token=");
    });

    it("accepts flows without a description (skill-engine prose flows)", async () => {
      const mockResponse = {
        flows: {
          travel_notice: {
            description: null,
            steps: [{ id: "autonomous", noop: true, next: "END" }],
          },
        },
        assistant_id: "test-assistant",
      };

      vi.mocked(global.fetch).mockResolvedValueOnce({
        ok: true,
        json: () => Promise.resolve(mockResponse),
      } as Response);

      const data = await getBotData({
        projectUrl: "http://localhost:5005",
        botDataEndpoint: "/data",
      });
      expect(data.flows["travel_notice"]?.description).toBe("");
    });
  });

  describe("getConversationHistory", () => {
    it("requests the plain URL when no credential is provided", async () => {
      const { requestedUrl } = await fetchConversationHistory();
      expect(requestedUrl).toBe(`${PROJECT_URL}${TRACKER_ENDPOINT}`);
    });

    it("appends the token query parameter for query transport, and no header", async () => {
      const { requestedUrl, requestInit } = await fetchConversationHistory({
        token: "my-secret-token",
        via: "query",
      });
      expect(requestedUrl).toBe(`${PROJECT_URL}${TRACKER_ENDPOINT}?token=my-secret-token`);
      expect(requestInit?.headers).not.toHaveProperty("Authorization");
    });

    it("sends a Bearer Authorization header for header transport, and no query token", async () => {
      const { requestedUrl, requestInit } = await fetchConversationHistory({
        token: "session-token-123",
        via: "header",
      });
      expect(requestInit?.headers).toMatchObject({
        Authorization: "Bearer session-token-123",
      });
      expect(requestedUrl).not.toContain("token=");
    });

    it("returns ProtoJSON events as received for the caller to dual-read", async () => {
      const protoMemory = {
        conversation_id: "test-session",
        timestamp: 1.5,
        memory_set: { key: "amount", value_json: "42" },
      };
      mockFetchOnce({
        ...TRACKER_RESPONSE,
        events: [protoMemory, { event: "user", text: "hi", timestamp: 2 }],
      });

      const tracker = await getConversationHistory({
        projectUrl: PROJECT_URL,
        trackerEndpoint: TRACKER_ENDPOINT,
      });

      expect(tracker.events[0]).toEqual(protoMemory);
      expect(tracker.events[1]).toMatchObject({ event: "user", text: "hi" });
    });
  });

  describe("credentialFingerprint", () => {
    it("never contains the raw credential", () => {
      const fingerprint = credentialFingerprint("Bearer super-secret-token");
      expect(fingerprint).not.toContain("super-secret-token");
    });

    it("changes when the credential changes", () => {
      expect(credentialFingerprint("Bearer a")).not.toBe(credentialFingerprint("Bearer b"));
    });

    it("is stable for the same credential and 'none' when absent", () => {
      expect(credentialFingerprint("Bearer a")).toBe(credentialFingerprint("Bearer a"));
      expect(credentialFingerprint(undefined)).toBe("none");
    });
  });
});
